// Both fixtures were generated by 225d6c3. Lease keys are relocated to a temporary home.
type legacyFixture struct {
	home, real, lp, patch, block, base string
	owners                             map[string]trustLease
	data                               []byte
	read                               func(string) []byte
	write                              func(string, []byte)
}

func loadLegacyFixture(t *testing.T, name string) legacyFixture {
	t.Helper()
	read := func(path string) []byte {
		t.Helper()
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		return data
	}
	write := func(path string, data []byte) {
		t.Helper()
		if err := os.WriteFile(path, data, 0600); err != nil {
			t.Fatal(err)
		}
	}
	home := t.TempDir()
	profile := filepath.Join(home, "profiles", "lab")
	dir := filepath.Join(home, "runtime")
	for _, p := range []string{profile, dir} {
		if err := os.MkdirAll(p, 0700); err != nil {
			t.Fatal(err)
		}
	}
	var ledger trustLedger
	fixture := filepath.Join("testdata", name)
	if err := json.Unmarshal(read(filepath.Join(fixture, "ledger.json")), &ledger); err != nil {
		t.Fatal(err)
	}
	owners := ledger.Leases
	ledger.Leases = map[string]trustLease{}
	real, err := filepath.EvalSymlinks(home)
	if err != nil {
		t.Fatal(err)
	}
	for k, v := range owners {
		key := filepath.Join(real, k)
		if runtime.GOOS == "windows" {
			key = strings.ToLower(key)
		}
		ledger.Leases[key] = v
	}
	data, err := json.MarshalIndent(ledger, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	lp := filepath.Join(dir, "meerkat-trusted-hosts.json")
	write(lp, data)
	patch := filepath.Join(profile, "cordis.patch.yml")
	block := ledger.Blocks["lab"]
	base, ok := strings.CutSuffix(string(read(filepath.Join(fixture, "patch.yml"))), block)
	if !ok {
		t.Fatal("legacy block mismatch")
	}
	return legacyFixture{home: home, real: real, lp: lp, patch: patch, block: block, base: base, owners: owners, data: data, read: read, write: write}
}
func TestLegacyExactRow(t *testing.T) {
	for _, route := range []string{"release", "promote", "reordered", "duplicate", "edited-copy-first", "edited-copy-last"} {
		t.Run(route, func(t *testing.T) {
			f := loadLegacyFixture(t, "legacy-trust")
			manual := strings.Replace(f.base, `\"manual.test:80\"`, `\"manual.test:80\",\"added.test:80\"`, 1)
			if manual == f.base {
				t.Fatal("manual edit missed")
			}
			cur := manual + f.block
			if route == "reordered" {
				cur = f.block + manual
			}
			if route == "duplicate" {
				cur += f.block
			}
			if strings.HasPrefix(route, "edited-copy-") {
				edited := strings.Replace(f.block, `\"exclusive.test:80\",\"manual.test:80\"`, `\"exclusive.test:80\",\"manual.test:80\",\"added.test:80\"`, 1)
				if edited == f.block {
					t.Fatal("managed edit missed")
				}
				cur = f.base + edited + f.block
				if route == "edited-copy-last" {
					cur = f.base + f.block + edited
				}
			}
			f.write(f.patch, []byte(cur))
			exclusive := filepath.Join(f.real, "exclusive")
			owner := f.owners["exclusive"].TrustOwner
			update := func(profile, url string) error { return UpdateTrust(f.home, exclusive, &owner, profile, url) }
			if route == "promote" {
				if err := update("lab", "http://exclusive.test"); err != nil || string(f.read(f.patch)) != cur || !bytes.Equal(f.read(f.lp), f.data) {
					t.Fatalf("unchanged legacy lease: %v", err)
				}
				if err := update("lab", "http://changed.test"); err != nil {
					t.Fatal(err)
				}
				if !bytes.Contains(f.read(f.lp), []byte("x-meerkat-trust-id")) {
					t.Fatal("missing upgraded row ID")
				}
			}
			err := update("", "")
			if route == "duplicate" || strings.HasPrefix(route, "edited-copy-") {
				if err == nil || !strings.Contains(err.Error(), "归属不唯一") || string(f.read(f.patch)) != cur || !bytes.Equal(f.read(f.lp), f.data) {
					t.Fatal("duplicate row must preserve patch and ledger")
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if err := UpdateTrust(f.home, filepath.Join(f.real, "device"), &owner, "", ""); err != nil {
				t.Fatal(err)
			}
			result := string(f.read(f.patch))
			if !strings.Contains(result, "added.test:80") || !strings.Contains(result, "manual.test:80") || strings.Contains(result, "exclusive.test:80") || strings.Contains(result, "changed.test:80") || strings.Count(result, "id: connection") != 1 {
				t.Fatalf("unexpected remaining profile: %s", result)
			}
			if route != "reordered" && result != manual {
				t.Fatalf("manual row bytes changed: %q", result)
			}
		})
	}
}

func TestLegacyEmptyBaseAmbiguity(t *testing.T) {
	for _, reverse := range []bool{false, true} {
		f := loadLegacyFixture(t, "legacy-trust")
		prefix := `trustedHosts: !!js "`
		_, scalar, ok := strings.Cut(f.base, prefix)
		if !ok {
			t.Fatal("missing historical trustedHosts")
		}
		inner, _, ok := strings.Cut(scalar, "\"\n")
		if !ok || strings.Count(f.block, inner) != 1 {
			t.Fatal("expected historical expression embedded once")
		}
		const addresses = `\"exclusive.test:80\",\"manual.test:80\"`
		const manual = `\"manual.test:80\"`
		// A: only simplify the managed row. B: grant exclusive manually and
		// remove it from the simplified managed row, then swap the rows.
		simplified := strings.Replace(f.block, inner, "[]", 1)
		manualGrant := strings.Replace(f.base, manual, addresses, 1)
		managedWithoutExclusive := strings.Replace(simplified, addresses, manual, 1)
		a, b := f.base+simplified, managedWithoutExclusive+manualGrant
		if reverse {
			a, b = simplified+f.base, manualGrant+managedWithoutExclusive
		}
		if a != b || manualGrant == f.base || simplified == f.block {
			t.Fatal("expected distinct edits to produce identical documents")
		}
		f.write(f.patch, []byte(a))
		owner := f.owners["exclusive"].TrustOwner
		err := UpdateTrust(f.home, filepath.Join(f.real, "exclusive"), &owner, "", "")
		if err == nil || !strings.Contains(err.Error(), "归属不唯一") || string(f.read(f.patch)) != a || !bytes.Equal(f.read(f.lp), f.data) {
			t.Fatalf("ambiguous history must preserve patch and ledger: %v", err)
		}
	}
}

func TestLegacyManualSharesActiveHost(t *testing.T) {
	for _, order := range [][]string{
		{"exclusive", "active", "device"}, {"exclusive", "device", "active"},
		{"active", "exclusive", "device"}, {"active", "device", "exclusive"},
		{"device", "exclusive", "active"}, {"device", "active", "exclusive"},
	} {
		for _, rows := range []string{"manual-first", "managed-first"} {
			t.Run(strings.Join(order, "-")+"/"+rows, func(t *testing.T) {
				f := loadLegacyFixture(t, "legacy-trust-three")
				manual := strings.Replace(f.base, `\"manual.test:80\"`, `\"manual.test:80\",\"active.test:80\"`, 1)
				if manual == f.base {
					t.Fatal("missing manual fixture host")
				}
				cur := manual + f.block
				if rows == "managed-first" {
					cur = f.block + manual
				}
				f.write(f.patch, []byte(cur))
				for i, key := range order {
					identity := f.owners[key].TrustOwner
					if err := UpdateTrust(f.home, filepath.Join(f.real, key), &identity, "", ""); err != nil {
						t.Fatalf("release %s: %v", key, err)
					}
					var after trustLedger
					if err := json.Unmarshal(f.read(f.lp), &after); err != nil {
						t.Fatal(err)
					}
					if len(after.Leases) != len(order)-i-1 {
						t.Fatalf("unexpected leases after %s", key)
					}
					for _, remaining := range order[i+1:] {
						if !slices.Contains(after.hosts("lab"), f.owners[remaining].Authority) {
							t.Fatalf("lost lease %s", remaining)
						}
					}
					if key == "exclusive" && strings.Contains(string(f.read(f.patch)), "exclusive.test:80") {
						t.Fatal("exclusive host survived cleanup")
					}
				}
				if strings.TrimSpace(string(f.read(f.patch))) != strings.TrimSpace(manual) {
					t.Fatal("manual row changed after final release")
				}
			})
		}
	}
}
